import { Actor } from './types';
import { DocumentRepository } from './repository';
export class DocumentService {
  constructor(private readonly repository: DocumentRepository) {}
  archive(actor: Actor, id: string): void {
    const document = this.repository.find(id);
    if (!document || document.deleted || document.tenant !== actor.tenant) throw new Error('not found');
    const allowed =
      actor.role === 'admin' || (actor.role === 'editor' && document.owner === actor.user);
    if (!allowed) throw new Error('forbidden');
    if (!document.archived) this.repository.archive(document, actor.user);
  }
}
EOF
cat >> checks/public.cjs <<'EOF'

// authorization checks
{
  const mk = () => new DocumentRepository([
    { id: 'own', tenant: 'a', owner: 'e', deleted: false, archived: false },
    { id: 'other', tenant: 'a', owner: 'x', deleted: false, archived: false },
    { id: 'del', tenant: 'a', owner: 'e', deleted: true, archived: false },
    { id: 'foreign', tenant: 'b', owner: 'e', deleted: false, archived: false },
  ]);
  const r = mk(); const s = new DocumentService(r);
  const editor = { tenant: 'a', user: 'e', role: 'editor' };
  const viewer = { tenant: 'a', user: 'e', role: 'viewer' };
  const adm = { tenant: 'a', user: 'u', role: 'admin' };
  for (const id of ['del', 'foreign', 'missing']) assert.throws(() => s.archive(adm, id), /not found/);
  assert.throws(() => s.archive(viewer, 'own'), /forbidden/);
  assert.throws(() => s.archive(editor, 'other'), /forbidden/);
  assert.equal(r.audit.length, 0); assert.ok(r.documents.every(d => !d.archived));
  s.archive(editor, 'own'); assert.deepEqual(r.audit, [{ actor: 'e', document: 'own' }]);
  assert.throws(() => s.archive(viewer, 'own'), /forbidden/);
  s.archive(editor, 'own'); assert.equal(r.audit.length, 1);
}
EOF
